INSERT INTO lexicon (slug, term, variants, definition, category, etymology, related_terms, translations) VALUES ('cursus-honorum', 'Cursus Honorum', '["Ämterlaufbahn"]', 'Der cursus honorum ("Lauf der Ehrenämter") war die festgelegte Abfolge politischer und militärischer Ämter in der römischen Republik, die ein Politiker durchlaufen musste, um an die Spitze des Staates zu gelangen. Die klassische Reihenfolge lautete: Quästor (Finanzverwalter, ab 30 Jahren) → Aedil (optional, Stadtverwalter) → Praetor (Richter und Befehlshaber, ab 39 Jahren) → Consul (höchstes Amt, ab 42 Jahren). Danach konnten ehemalige Konsuln noch Censor werden. Zwischen den Ämtern mussten mindestens zwei Jahre liegen (Biennium). Der cursus honorum sollte sicherstellen, dass nur erfahrene und erprobte Männer in die höchsten Positionen gelangten.', 'Politik', 'Lateinisch ''cursus honorum'' - Lauf der Ehren/Ämter. Die Bezeichnung betont die systematische Abfolge der magistratischen Karriere.', '["Quästor","Aedil","Praetor","Consul","Censor"]', '{"en":{"term":"Cursus Honorum","definition":"The cursus honorum (''course of honors'') was the established sequence of political and military offices in the Roman Republic that a politician had to go through to reach the top of the state. The classic sequence was: Quaestor (financial administrator, from age 30) → Aedile (optional, city administrator) → Praetor (judge and commander, from age 39) → Consul (highest office, from age 42). Thereafter, former consuls could still become Censor. At least two years had to pass between offices (Biennium). The cursus honorum was intended to ensure that only experienced and proven men reached the highest positions.","etymology":"Latin ''cursus honorum'' - course of honors/offices. The term emphasizes the systematic sequence of the magisterial career.","category":"Politics","variants":["Course of Honors"]},"la":{"term":"Cursus Honorum","definition":"Cursus honorum fuit series ordinata magistratuum politicorum et militarium in re publica Romana quam politicus percurrere debebat ut ad summum civitatis perveniret. Series classica erat: Quaestor (administrator pecuniae, ab XXX annis) → Aedilis (optionalis, administrator urbis) → Praetor (iudex et imperator, ab XXXIX annis) → Consul (magistratus summus, ab XLII annis). Postea, ex-consules adhuc censor fieri poterant. Inter magistratus minimum duo anni intercedere debebant (Biennium). Cursus honorum destinatus erat ut solum viri experti et probati ad positiones summas pervenirent.","etymology":"Latine ''cursus honorum'' - cursus honorum/magistratuum. Nomen seriem systematicam cursus magistratualis emphasizat.","category":"Res Publica","variants":[]}}');
INSERT INTO lexicon (slug, term, variants, definition, category, etymology, related_terms, translations) VALUES ('virtus', 'Virtus', '["Tugend","Tapferkeit"]', 'Virtus (lat. "Mannhaftigkeit", "Tugend") war einer der zentralen Werte der römischen Kultur und bezeichnete ursprünglich militärische Tapferkeit und Mannesmut (von ''vir'' = Mann). Im Lauf der Zeit erweiterte sich die Bedeutung zu umfassender moralischer Exzellenz: Charakterstärke, Pflichterfüllung, Selbstbeherrschung und tugendhaftes Verhalten in allen Lebensbereichen. Virtus stand im Zentrum des römischen Ehrenkodex und war eng mit anderen Kernwerten wie pietas (Pflichtgefühl), dignitas (Würde) und gravitas (Ernst) verbunden. Sie war die Grundlage für den Anspruch auf auctoritas (Autorität) und damit für politischen Einfluss. Römische Feldherren und Staatsmänner wurden an ihrer virtus gemessen.', 'Philosophie & Werte', 'Von lateinisch ''vir'' (Mann) → ''virtus'' (Mannhaftigkeit, Tugend). Ursprünglich eng mit militärischer Tapferkeit verbunden.', '["Pietas","Dignitas","Gravitas","Auctoritas"]', '{"en":{"term":"Virtus","definition":"Virtus (Latin ''manliness'', ''virtue'') was one of the central values of Roman culture and originally denoted military bravery and manly courage (from ''vir'' = man). Over time, the meaning expanded to comprehensive moral excellence: strength of character, fulfillment of duty, self-control, and virtuous behavior in all areas of life. Virtus stood at the center of the Roman code of honor and was closely linked to other core values such as pietas (sense of duty), dignitas (dignity), and gravitas (seriousness). It was the foundation for the claim to auctoritas (authority) and thus for political influence. Roman generals and statesmen were measured by their virtus.","etymology":"From Latin ''vir'' (man) → ''virtus'' (manliness, virtue). Originally closely associated with military bravery.","category":"Philosophy & Values","variants":["Virtue"]},"la":{"term":"Virtus","definition":"Virtus fuit unus ex valoribus centralibus culturae Romanae et initio fortitudinem militarem et animum virilem (a ''vir'' = vir) designabat. Temporis progressu, significatio ad excellentiam moralem comprehensivam extensa est: robur characteris, officii impletio, temperantia et mores virtuosi in omnibus vitae partibus. Virtus in centro codicis honoris Romani stabat et cum aliis valoribus nuclearibus ut pietas (sensus officii), dignitas, et gravitas stricte coniuncta erat. Fundamentum erat pro praetensione ad auctoritatem et ita pro influxu politico. Imperatores et viri publici Romani ex virtute sua mensurabantur.","etymology":"A vocabulo Latino ''vir'' (vir) → ''virtus'' (virilitas, virtus). Initio stricte cum fortitudine militari coniuncta.","category":"Philosophia et Valores","variants":[]}}');
INSERT INTO lexicon (slug, term, variants, definition, category, etymology, related_terms, translations) VALUES ('pietas', 'Pietas', '["Pflichtgefühl","Frömmigkeit"]', 'Pietas war ein fundamentaler Wert der römischen Gesellschaft und bezeichnete die Pflichterfüllung und Frömmigkeit gegenüber den Göttern, der Familie und dem Staat. Der Begriff umfasste mehrere Dimensionen: religiöse Frömmigkeit (Verehrung der Götter), familiäre Pietät (Respekt vor Eltern und Ahnen), und staatsbürgerliche Pflichterfüllung (Loyalität zur res publica). Pietas war die Grundlage des römischen Wertesystems und galt als unverzichtbare Tugend für jeden römischen Bürger. Vergils Aeneas wird wiederholt als ''pius Aeneas'' (der fromme Aeneas) beschrieben, weil er trotz persönlicher Opfer seine Pflicht gegenüber den Göttern und seinem Volk erfüllt. Das lateinische Wort ist die Wurzel des deutschen "Pietät".', 'Philosophie & Werte', 'Von lateinisch ''pius'' (fromm, pflichtbewusst) → ''pietas''. Die Wurzel indogermanisch *peH- deutet auf Reinheit und Pflichterfüllung hin.', '["Virtus","Dignitas","Fides","Auctoritas"]', '{"en":{"term":"Pietas","definition":"Pietas was a fundamental value of Roman society and denoted the fulfillment of duty and piety toward the gods, family, and state. The concept encompassed multiple dimensions: religious piety (worship of the gods), familial piety (respect for parents and ancestors), and civic duty (loyalty to the res publica). Pietas was the foundation of the Roman value system and was considered an indispensable virtue for every Roman citizen. Vergil''s Aeneas is repeatedly described as ''pius Aeneas'' (pious Aeneas) because he fulfills his duty to the gods and his people despite personal sacrifices. The Latin word is the root of English ''piety''.","etymology":"From Latin ''pius'' (pious, dutiful) → ''pietas''. The Indo-European root *peH- suggests purity and fulfillment of duty.","category":"Philosophy & Values","variants":["Piety"]},"la":{"term":"Pietas","definition":"Pietas fuit valor fundamentalis societatis Romanae et officii impletionem et pietatem erga deos, familiam et civitatem designabat. Conceptus plures dimensiones comprehendebat: pietatem religiosam (cultum deorum), pietatem familiarem (respectum erga parentes et maiores), et officium civile (fidelitatem ad rem publicam). Pietas fundamentum systematis valoris Romani erat et ut virtus indispensabilis pro omni cive Romano habebatur. Aeneas Vergilii iterum ut ''pius Aeneas'' describitur quia officium suum erga deos et populum suum malgre sacrificia personalia implet. Vocabulum Latinum radix est vocabuli Anglici ''piety''.","etymology":"A vocabulo Latino ''pius'' (pius, officiosus) → ''pietas''. Radix Indoeuropaea *peH- puritatem et officii impletionem suggerit.","category":"Philosophia et Valores","variants":[]}}');
INSERT INTO lexicon (slug, term, variants, definition, category, etymology, related_terms, translations) VALUES ('dignitas', 'Dignitas', '["Würde","Ansehen"]', 'Dignitas bezeichnete in der römischen Gesellschaft die persönliche Würde, das Ansehen und den gesellschaftlichen Rang eines Bürgers. Sie wurde durch Leistungen im Dienst des Staates, militärische Erfolge, politische Ämter und vorbildliches Verhalten erworben und musste ständig verteidigt werden. Dignitas war ein zentraler Wert der römischen Oberschicht (Nobilität) und eng mit dem Konzept der Honor (Ehre) verbunden. Der Verlust der dignitas war eine schwere Demütigung. Caesar rechtfertigte den Bürgerkrieg mit der Verteidigung seiner dignitas – er sah sie durch Pompeius und den Senat bedroht. Die dignitas bestimmte den sozialen Status und den politischen Einfluss in Rom.', 'Philosophie & Werte', 'Von lateinisch ''dignus'' (würdig, wert) → ''dignitas''. Die Wurzel bedeutet "passend", "angemessen", "seiner Stellung entsprechend".', '["Virtus","Pietas","Auctoritas","Gravitas","Honor"]', '{"en":{"term":"Dignitas","definition":"Dignitas denoted personal dignity, prestige, and social rank of a citizen in Roman society. It was acquired through service to the state, military successes, political offices, and exemplary behavior, and had to be constantly defended. Dignitas was a central value of the Roman upper class (nobility) and closely linked to the concept of honor (honor). Loss of dignitas was a severe humiliation. Caesar justified the Civil War by defending his dignitas – he saw it threatened by Pompey and the Senate. Dignitas determined social status and political influence in Rome.","etymology":"From Latin ''dignus'' (worthy, deserving) → ''dignitas''. The root means ''fitting'', ''appropriate'', ''befitting one''s position''.","category":"Philosophy & Values","variants":["Dignity"]},"la":{"term":"Dignitas","definition":"Dignitas in societate Romana dignitatem personalem, praestantiam et gradum socialem civis designabat. Per merita in servitio civitatis, successus militares, magistratus politicos et mores exemplares acquirebatur et constanter defendi debebat. Dignitas valor centralis classis superioris Romanae (nobilitatis) erat et cum conceptu honoris stricte coniuncta. Amissio dignitatis contumelia gravis erat. Caesar bellum civile defensione dignitatis suae iustificavit – eam a Pompeio et senatu minatam videbat. Dignitas statum socialem et influxum politicum Romae determinabat.","etymology":"A vocabulo Latino ''dignus'' (dignus, meritus) → ''dignitas''. Radix significat ''conveniens'', ''aptus'', ''conditioni suae conveniens''.","category":"Philosophia et Valores","variants":[]}}');
INSERT INTO lexicon (slug, term, variants, definition, category, etymology, related_terms, translations) VALUES ('auctoritas', 'Auctoritas', '["Autorität","Einfluss"]', 'Auctoritas war in Rom das persönliche Ansehen, die moralische Autorität und der gesellschaftliche Einfluss einer Person, unabhängig von formalen Machtbefugnissen (potestas). Sie beruhte auf virtus (Tugend), dignitas (Würde), Lebenserfahrung, Verdiensten und Weisheit. Senatoren und Patrizier besaßen auctoritas kraft ihrer Stellung und ihres Lebenswerks. Augustus bezeichnete sich als "princeps" (Erster) nicht durch Macht, sondern durch auctoritas – er beanspruchte moralische Führerschaft, ohne formell König oder Diktator zu sein. Auctoritas war subtiler und oft wirksamer als bloße Macht: Ein Rat von jemandem mit hoher auctoritas wurde befolgt, ohne dass Zwang nötig war. Der Begriff ist die Wurzel des deutschen "Autorität".', 'Philosophie & Werte', 'Von lateinisch ''augere'' (vermehren, wachsen lassen) → ''auctor'' (Urheber, Förderer) → ''auctoritas''. Die Wurzel deutet auf Wachstum und Förderung hin.', '["Dignitas","Virtus","Potestas","Imperium"]', '{"en":{"term":"Auctoritas","definition":"Auctoritas in Rome was personal prestige, moral authority, and social influence of a person, independent of formal powers (potestas). It was based on virtus (virtue), dignitas (dignity), life experience, merits, and wisdom. Senators and patricians possessed auctoritas by virtue of their position and life''s work. Augustus called himself ''princeps'' (First) not through power but through auctoritas – he claimed moral leadership without formally being king or dictator. Auctoritas was subtler and often more effective than mere power: advice from someone with high auctoritas was followed without coercion. The term is the root of the English ''authority''.","etymology":"From Latin ''augere'' (to increase, make grow) → ''auctor'' (originator, promoter) → ''auctoritas''. The root suggests growth and promotion.","category":"Philosophy & Values","variants":["Authority"]},"la":{"term":"Auctoritas","definition":"Auctoritas Romae fuit praestantia personalis, auctoritas moralis et influxus socialis personae, independens a potestatibus formalibus (potestas). In virtute, dignitate, experientia vitae, meritis et sapientia fundabatur. Senatores et patricii auctoritatem vi positionis suae et operis vitae possidebant. Augustus se ''princeps'' (Primus) vocavit non per potestatem sed per auctoritatem – ducatum moralem praetendebat sine formaliter rex vel dictator esse. Auctoritas subtilior et saepe efficacior quam mera potestas erat: consilium alicuius cum auctoritate alta sequebantur sine coercitione necessaria. Vocabulum radix vocabuli Anglici ''authority'' est.","etymology":"A verbo Latino ''augere'' (augere, crescere facere) → ''auctor'' (auctor, promotor) → ''auctoritas''. Radix crescentiam et promotionem suggerit.","category":"Philosophia et Valores","variants":[]}}');
INSERT INTO lexicon (slug, term, variants, definition, category, etymology, related_terms, translations) VALUES ('gravitas', 'Gravitas', '["Ernst","Würde"]', 'Gravitas (lat. "Schwere", "Gewicht") bezeichnete in der römischen Kultur eine Charaktereigenschaft, die Ernst, Würde, Besonnenheit und moralisches Gewicht umfasste. Ein Mann mit gravitas war ernsthaft, selbstbeherrscht, würdevoll in seinem Auftreten und bedacht in seinen Entscheidungen. Diese Eigenschaft war besonders wichtig für Senatoren, Richter und Staatsmänner. Gravitas stand im Gegensatz zu levitas (Leichtfertigkeit) und war eng verbunden mit constantia (Standhaftigkeit) und prudentia (Klugheit). Cato der Ältere galt als Inbegriff römischer gravitas. Wer gravitas besaß, strahlte natürliche Autorität aus und wurde ernst genommen.', 'Philosophie & Werte', 'Von lateinisch ''gravis'' (schwer, gewichtig) → ''gravitas''. Das physische "Gewicht" wurde auf moralisches Gewicht übertragen.', '["Dignitas","Auctoritas","Constantia","Prudentia"]', '{"en":{"term":"Gravitas","definition":"Gravitas (Latin ''heaviness'', ''weight'') denoted a character trait in Roman culture that encompassed seriousness, dignity, prudence, and moral weight. A man with gravitas was serious, self-controlled, dignified in demeanor, and deliberate in decisions. This quality was particularly important for senators, judges, and statesmen. Gravitas stood in contrast to levitas (frivolity) and was closely connected with constantia (steadfastness) and prudentia (wisdom). Cato the Elder was considered the epitome of Roman gravitas. Those who possessed gravitas radiated natural authority and were taken seriously.","etymology":"From Latin ''gravis'' (heavy, weighty) → ''gravitas''. The physical ''weight'' was transferred to moral weight.","category":"Philosophy & Values","variants":[]},"la":{"term":"Gravitas","definition":"Gravitas in cultura Romana proprietatem characteris designabat quae severitatem, dignitatem, prudentiam et pondus morale comprehendebat. Vir cum gravitate serius, temperatus, dignus in gestu et consideratus in decisionibus erat. Haec proprietas praesertim pro senatoribus, iudicibus et viris publicis magna erat. Gravitas contra levitatem stabat et cum constantia et prudentia stricte coniuncta erat. Cato Maior typus gravitatis Romanae habebatur. Qui gravitatem possidebat, auctoritatem naturalem radiabat et serio accipiebatur.","etymology":"A vocabulo Latino ''gravis'' (gravis, ponderosus) → ''gravitas''. ''Pondus'' physicum ad pondus morale transferebatur.","category":"Philosophia et Valores","variants":[]}}');
INSERT INTO lexicon (slug, term, variants, definition, category, etymology, related_terms, translations) VALUES ('mos-maiorum', 'Mos Maiorum', '["Sitte der Vorfahren","Tradition"]', 'Mos maiorum (lat. "Sitte der Vorfahren") bezeichnete das ungeschriebene Gesetz der überlieferten Sitten, Bräuche und Werte, die von den Ahnen vererbt wurden und die römische Gesellschaft prägten. Es war kein formales Gesetzbuch, sondern ein moralischer und sozialer Verhaltenskodex, der als verbindlich galt. Zum mos maiorum gehörten Werte wie pietas (Pflichtgefühl), virtus (Tugend), fides (Treue) und gravitas (Ernst). Die Römer beriefen sich ständig auf den mos maiorum, um politische Entscheidungen zu legitimieren oder Neuerungen abzulehnen. Konservative Politiker wie Cato der Ältere verteidigten den mos maiorum gegen griechische Einflüsse und Dekadenz. In der Krise der späten Republik wurde der Verfall des mos maiorum beklagt.', 'Kultur & Gesellschaft', 'Lateinisch ''mos'' (Sitte, Brauch) + ''maiorum'' (Genitiv Plural von ''maior'' = größer, älter). Wörtlich: "die Sitte der Größeren/Älteren", d.h. der Vorfahren.', '["Pietas","Virtus","Fides","Gravitas","Traditio"]', '{"en":{"term":"Mos Maiorum","definition":"Mos maiorum (Latin ''custom of the ancestors'') denoted the unwritten law of transmitted customs, practices, and values inherited from ancestors that shaped Roman society. It was not a formal legal code but a moral and social code of conduct considered binding. The mos maiorum included values such as pietas (sense of duty), virtus (virtue), fides (loyalty), and gravitas (seriousness). Romans constantly invoked the mos maiorum to legitimize political decisions or reject innovations. Conservative politicians like Cato the Elder defended the mos maiorum against Greek influences and decadence. In the crisis of the late Republic, the decline of the mos maiorum was lamented.","etymology":"Latin ''mos'' (custom, practice) + ''maiorum'' (genitive plural of ''maior'' = greater, older). Literally: ''the custom of the greater/older ones'', i.e., the ancestors.","category":"Culture & Society","variants":["Way of the Ancestors"]},"la":{"term":"Mos Maiorum","definition":"Mos maiorum legem non scriptam morum, consuetudinum et valorum a maioribus hereditatorum designabat quae societatem Romanam formabant. Non codex legalis formalis sed codex moralis et socialis morum erat qui ut obligatorius habebatur. Ad mos maiorum valores ut pietas, virtus, fides et gravitas pertinebant. Romani constanter ad mos maiorum appellebant ut decisiones politicas legitimarent vel innovationes reicerent. Politici conservativi ut Cato Maior mos maiorum contra influxus Graecos et decadentiam defenderunt. In crisi rei publicae serae, corruptio mos maiorum lamentabatur.","etymology":"Latine ''mos'' (mos, consuetudo) + ''maiorum'' (genitivus pluralis de ''maior'' = maior, senior). Litteraliter: ''mos maiorum/seniorum'', i.e., maiorum.","category":"Cultura et Societas","variants":[]}}');
INSERT INTO lexicon (slug, term, variants, definition, category, etymology, related_terms, translations) VALUES ('clientela', 'Clientela', '["Klientelsystem"]', 'Die Clientela war ein fundamentales soziales System im antiken Rom, das auf gegenseitigen Verpflichtungen zwischen einem Patron (patronus) und seinen Klienten (clientes) beruhte. Der Patron, meist ein wohlhabender und einflussreicher Mann, bot seinen Klienten Schutz, Rechtsvertretung, finanzielle Unterstützung und politischen Beistand. Im Gegenzug schuldeten die Klienten ihrem Patron Loyalität, Gehorsam und politische Unterstützung (z.B. bei Wahlen). Die Beziehung war erblich und galt als heilig (fides). Jeden Morgen empfing der Patron seine Klienten zur salutatio (Morgenbegrüßung). Das Clientelsystem durchdrang die gesamte römische Politik und Gesellschaft und war eine der Hauptquellen politischer Macht.', 'Kultur & Gesellschaft', 'Von lateinisch ''cliens'' (Klient, Schützling) → ''clientela''. Die Wurzel ist möglicherweise mit ''cluere'' (hören, gehorchen) verwandt.', '["Patronus","Fides","Salutatio"]', '{"en":{"term":"Clientela","definition":"The clientela was a fundamental social system in ancient Rome based on mutual obligations between a patron (patronus) and his clients (clientes). The patron, usually a wealthy and influential man, offered his clients protection, legal representation, financial support, and political assistance. In return, clients owed their patron loyalty, obedience, and political support (e.g., in elections). The relationship was hereditary and considered sacred (fides). Every morning, the patron received his clients for the salutatio (morning greeting). The client system permeated all of Roman politics and society and was one of the main sources of political power.","etymology":"From Latin ''cliens'' (client, protégé) → ''clientela''. The root is possibly related to ''cluere'' (to hear, obey).","category":"Culture & Society","variants":["Client System"]},"la":{"term":"Clientela","definition":"Clientela fuit systema sociale fundamentale in Roma antiqua quod in obligationibus mutuis inter patronum et clientes suos fundabatur. Patronus, plerumque vir dives et influxus, clientibus suis protectionem, repraesentationem legalem, supportum pecuniarium et assistentiam politicam offerebat. Vice versa, clientes patrono suo fidelitatem, obedientiam et supportum politicum (e.g., in comitiis) debebant. Relatio hereditaria erat et ut sacra (fides) habebatur. Quaque mane, patronus clientes suos ad salutationem accipiebat. Systema clientelare omnem politicam et societatem Romanam pervadebat et una ex fontibus principalibus potentiae politicae erat.","etymology":"A vocabulo Latino ''cliens'' (cliens, protectus) → ''clientela''. Radix fortasse cum ''cluere'' (audire, oboedire) cognata est.","category":"Cultura et Societas","variants":[]}}');
INSERT INTO lexicon (slug, term, variants, definition, category, etymology, related_terms, translations) VALUES ('patronus', 'Patronus', '["Schutzherr"]', 'Der Patronus (Schutzherr) war im römischen Clientelsystem der sozial höherstehende Partner, der seinen Klienten (clientes) Schutz, Unterstützung und Förderung bot. Patrone waren meist wohlhabende Senatoren, Ritter oder einflussreiche Bürger. Sie vertraten ihre Klienten vor Gericht, halfen ihnen finanziell in Notlagen, verschafften ihnen Ämter und Aufträge, und boten politischen Beistand. Dafür erwarteten sie Loyalität, Gehorsam und politische Unterstützung (Wahlstimmen, Gefolge bei öffentlichen Auftritten). Die Patron-Klient-Beziehung war lebenslang und vererblich. Freigelassene (Liberti) blieben automatisch Klienten ihres ehemaligen Herrn. Das Patronatssystem war eine der Säulen römischer Macht und sozialer Ordnung.', 'Kultur & Gesellschaft', 'Von lateinisch ''pater'' (Vater) → ''patronus'' (väterlicher Beschützer). Der Patron übernahm eine quasi-väterliche Fürsorgerolle.', '["Clientela","Cliens","Fides","Libertus"]', '{"en":{"term":"Patronus","definition":"The patronus (patron) in the Roman client system was the socially superior partner who offered his clients (clientes) protection, support, and advancement. Patrons were usually wealthy senators, knights, or influential citizens. They represented their clients in court, helped them financially in emergencies, procured offices and contracts for them, and provided political assistance. In return, they expected loyalty, obedience, and political support (votes, retinue at public appearances). The patron-client relationship was lifelong and hereditary. Freedmen (liberti) automatically remained clients of their former master. The patronage system was one of the pillars of Roman power and social order.","etymology":"From Latin ''pater'' (father) → ''patronus'' (paternal protector). The patron assumed a quasi-paternal care role.","category":"Culture & Society","variants":["Patron"]},"la":{"term":"Patronus","definition":"Patronus in systemate clientelari Romano fuit socius socialiter superior qui clientibus suis (clientes) protectionem, supportum et promotionem offerebat. Patroni plerumque senatores divites, equites vel cives influxus erant. Clientes suos coram iudicio repraesentabant, eis pecuniarie in necessitatibus adiuvabant, magistratus et contractus eis procurabant, et assistentiam politicam praebebant. Vice versa, fidelitatem, obedientiam et supportum politicum (suffragia, comitatum in apparitionibus publicis) exspectabant. Relatio patroni-clientis vitam longam et hereditariam erat. Liberti automatice clientes domini pristini manebant. Systema patronatus una ex columnis potentiae Romanae et ordinis socialis erat.","etymology":"A vocabulo Latino ''pater'' (pater) → ''patronus'' (protector paternus). Patronus rolum curae quasi-paternae assumebat.","category":"Cultura et Societas","variants":[]}}');
INSERT INTO lexicon (slug, term, variants, definition, category, etymology, related_terms, translations) VALUES ('fides', 'Fides', '["Treue","Vertrauen"]', 'Fides war einer der grundlegendsten Werte der römischen Kultur und bezeichnete Treue, Vertrauen, Verlässlichkeit und die Einhaltung von Zusagen. Fides galt als göttliche Tugend (personifiziert als Göttin Fides) und war die Basis aller zwischenmenschlichen und politischen Beziehungen: Verträge, Bündnisse (foedus), Eide, Patron-Klient-Beziehungen und Freundschaften beruhten auf fides. Wer seine fides brach, verlor seine Ehre und sein Ansehen vollständig. Die Römer sahen sich selbst als besonders treu und verlässlich – ein Grund für ihren Erfolg in der Außenpolitik. "Fidem servare" (die Treue wahren) und "fidem frangere" (die Treue brechen) waren zentrale Kategorien römischer Moralität. Das lateinische Wort ist die Wurzel des deutschen "Fidel" (treu).', 'Philosophie & Werte', 'Von indogermanisch *bheidh- (vertrauen) → lateinisch ''fides''. Verwandt mit ''fidere'' (vertrauen) und ''foedus'' (Vertrag, Bündnis).', '["Pietas","Clientela","Foedus","Iusiurandum"]', '{"en":{"term":"Fides","definition":"Fides was one of the most fundamental values of Roman culture and denoted loyalty, trust, reliability, and keeping one''s word. Fides was considered a divine virtue (personified as the goddess Fides) and was the basis of all interpersonal and political relationships: contracts, alliances (foedus), oaths, patron-client relationships, and friendships were based on fides. Anyone who broke their fides lost their honor and prestige completely. Romans saw themselves as particularly loyal and reliable – a reason for their success in foreign policy. ''Fidem servare'' (to keep faith) and ''fidem frangere'' (to break faith) were central categories of Roman morality. The Latin word is the root of English ''fidelity''.","etymology":"From Indo-European *bheidh- (to trust) → Latin ''fides''. Related to ''fidere'' (to trust) and ''foedus'' (treaty, alliance).","category":"Philosophy & Values","variants":["Faith","Loyalty"]},"la":{"term":"Fides","definition":"Fides fuit unus ex valoribus fundamentalissimis culturae Romanae et fidelitatem, fiduciam, fidem et observantiam promissorum designabat. Fides ut virtus divina (personificata ut dea Fides) habebatur et basis omnium relationum interpersonalium et politicarum erat: contractus, foedera, iuramenta, relationes patroni-clientis et amicitiae in fide fundabantur. Qui fidem frangébat, honorem et praestantiam suam complete amittebat. Romani se ipsos ut praesertim fideles et fideles videbant – ratio successus eorum in politica externa. ''Fidem servare'' et ''fidem frangere'' categoriae centrales moralitatis Romanae erant. Vocabulum Latinum radix vocabuli Anglici ''fidelity'' est.","etymology":"Ab Indoeuropaeo *bheidh- (fidere) → Latine ''fides''. Cognatum cum ''fidere'' (fidere) et ''foedus'' (tractatus, foedus).","category":"Philosophia et Valores","variants":[]}}');
